#include <bits/stdc++.h>

using namespace std;

string s;

int main() {
    int n, k;
    cin >> n >> k >> s;
    s = "Y" + s + "Y";

    queue<int> q;
    int d = 0, mn = 0, ok = 0;

    for (int i = 0; i <= n + 1; i++) {
        while (q.size() && i - q.front() - 1 > k) q.pop();

        if (s[i] != 'N') {
            if (q.size() && i - q.front() - 1 == k) ok = 1;
            d = 0;
            if (s[i] == 'Y')
                while (q.size()) q.pop();
            q.push(i);
        } else {
            mn = max(mn, ++d);
        }
    }

    if (ok && mn <= k) cout << "YES" << endl;
    else cout << "NO" << endl;
}

